#!/usr/bin/env python3
"""Reachability analysis for chips/bk7258 sources.

Roots come from BOTH build systems (CMakeLists.txt and Make.defs), plus the
configure_file wrapper generator for the WPA sources.  From those roots we
follow #include of .c/.inc files, because this tree compiles vendor code by
including it into a thin team-owned wrapper translation unit.

Anything not reachable is a translation unit nothing can ever compile.
"""
import os
import re
import subprocess
import sys

ROOT = "/home/czp/openvela_contest/.worktrees/bk7258-wifi-rebuild"
CHIP = os.path.join(ROOT, "chips/bk7258")

BUILD_FILES = [
    "chips/bk7258/CMakeLists.txt",
    "chips/bk7258/Make.defs",
    "chips/bk7258/wifi/CMakeLists.txt",
    "chips/bk7258/wifi/Make.defs",
    "chips/bk7258/audio/CMakeLists.txt",
]

# All tracked .c/.inc under chips/bk7258
tracked = subprocess.run(
    ["git", "ls-files", "chips/bk7258"],
    cwd=ROOT, capture_output=True, text=True, check=True,
).stdout.split()
sources = {p for p in tracked if p.endswith((".c", ".inc"))}

# ---- roots: strip comments first, then take path-like .c tokens -------------
roots = set()
for bf in BUILD_FILES:
    path = os.path.join(ROOT, bf)
    if not os.path.exists(path):
        continue
    base = os.path.dirname(bf)
    for line in open(path, encoding="utf-8", errors="replace"):
        code = line.split("#", 1)[0]          # both CMake and Make use #
        for m in re.finditer(r"[A-Za-z0-9_./+-]+\.c\b", code):
            tok = m.group(0)
            cand = os.path.normpath(os.path.join(base, tok))
            if cand in sources:
                roots.add(cand)

# ---- follow #include "...c" / "...inc" chains -------------------------------
def includes_of(relpath):
    out = set()
    full = os.path.join(ROOT, relpath)
    try:
        text = open(full, encoding="utf-8", errors="replace").read()
    except OSError:
        return out
    d = os.path.dirname(relpath)
    for m in re.finditer(r'#\s*include\s+"([^"]+\.(?:c|inc))"', text):
        cand = os.path.normpath(os.path.join(d, m.group(1)))
        if cand in sources:
            out.add(cand)
    return out

reachable, stack = set(roots), list(roots)
while stack:
    cur = stack.pop()
    for nxt in includes_of(cur):
        if nxt not in reachable:
            reachable.add(nxt)
            stack.append(nxt)

dead = sorted(sources - reachable)

def lines(p):
    try:
        return sum(1 for _ in open(os.path.join(ROOT, p), "rb"))
    except OSError:
        return 0

print(f"tracked .c/.inc : {len(sources)}")
print(f"roots (in build): {len(roots)}")
print(f"reachable       : {len(reachable)}")
print(f"DEAD            : {len(dead)}  ({sum(lines(p) for p in dead)} lines)")
print()

# ---- classify dead files ---------------------------------------------------
def kind(p):
    if "/third_party/" in p:
        return "third_party (authority import)"
    if "/authority" in p:
        return "authority/ (authority import)"
    return "team-owned"

groups = {}
for p in dead:
    groups.setdefault(kind(p), []).append(p)

for k in ("team-owned", "authority/ (authority import)",
          "third_party (authority import)"):
    if k not in groups:
        continue
    g = groups[k]
    print(f"=== {k}: {len(g)} files, {sum(lines(p) for p in g)} lines")
    for p in sorted(g, key=lambda x: -lines(x)):
        print(f"  {lines(p):6d}  {p[len('chips/bk7258/'):]}")
    print()

